package com.wipro.hibernate;import jakarta.persistence.*;@Entity @Table(name="CAR_DETAILS") public class CarDetail{@Id @Column(name="REGNO") private String regNo;@Column(name="MODEL")private String model;@Column(name="COLOR")private String color;@Column(name="MANUFACTURER")private String manufacturer;public CarDetail(){}public CarDetail(String r,String m,String c,String f){regNo=r;model=m;color=c;manufacturer=f;}public String getRegNo(){return regNo;}public String getModel(){return model;}public String getColor(){return color;}public String getManufacturer(){return manufacturer;}}